INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12055, 'ሕንጉጉ ሕማቓት እዮሞ', 'tigrigna', 'ሓደ እዋን ድርቂ ነበረ። ኣቦይ ሃፍቱ ምስ ቤተሰቦም ምግቢ ይደልዩ ነበሩ። ሓደ ልሙዕ ደን ይረኽቡ እሞ እቲ በዓልዋና ክበልዑ ፈቐደሎም።እቲ ምግቢ ንኽበልዑ ግን ዓቢይ ፈተና ክሓልፉ ኣለዎም። Nível: First words. Ilustração: Natalie Propa.', 'http://africanstorybook.org/illustrations/covers/21103.png', NULL, 2045, 35, 30, 'asp-21103', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12056, 'ንእንሳት እግሪ ተዋሃቦም', 'tigrigna', 'ኩሎም እንስሳት ከም ሰብ ብእግሮም ምእንቲ ክኸዱ ፈጣሪ እግሪ ክህቦም ወሲኑ። Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21104.png', NULL, 2045, 35, 30, 'asp-21104', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12057, 'ኣንጭዋን ድሙን', 'tigrigna', 'ሓንቲ ለባም ሽማግለ ኣንጭዋ ፀላኢና ፈታዊ መሲሉ እንትቐርብ፣ ክንርሕቖ ከም ዘለና ኣምሂራትና። Nível: First words. Ilustração: Jacob Kono.', 'http://africanstorybook.org/illustrations/covers/21105.png', NULL, 2045, 35, 30, 'asp-21105', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12058, 'እናሓጎይ፣ ማንቲለን ሓርማዝን', 'tigrigna', 'እናሓጎኦም ምሸት ምሸት ከመይ ነበረያነበረ ትነግሮም ከም ዝነበረት ሓደ ቖልዓ ዝተዛረቦ። Nível: First words. Ilustração: lang:	Tigrigna.', 'http://africanstorybook.org/illustrations/covers/21106.png', NULL, 2045, 35, 30, 'asp-21106', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12059, 'ገዝሚ', 'tigrigna', 'እዚ ታሪኽ ብዛዕባ ሓደ ወዲን ካብ እናሓጉኡ ዝተዋሃበቶ እንቋቕሖን እዩ።እቲ ወዲ ነታ እንቋቕሖ ብትኽክል ኣይሓዛን ፤ ዕድለኛ ኾይኑ ግን ናብ ፅቡቕ መሪሓቶ። Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21108.png', NULL, 2045, 35, 30, 'asp-21108', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12060, 'ዘየመስግን ተኹላ', 'tigrigna', 'ማንቲለ ንተኹላ ካብ ከቢድ ፀገም ኣድሒንዎ። ተኹላ ግን ክንዲ ንማንቲለ ኣመስጊኑ ዝሽልሞ ቓሉ ዓፀፈ። Nível: First words. Ilustração: Jacob Kono.', 'http://africanstorybook.org/illustrations/covers/21109.png', NULL, 2045, 35, 30, 'asp-21109', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12061, 'Nonkungu Ne Imbulu', 'oluwanga', 'Nonkungu is sent to her rich uncle who lives in another village by her parents. Shes very excited and shes got on a beautiful beaded dress made by her mother. On her way to her uncles village Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/2111.png', NULL, 1146, 35, 30, 'asp-2111', 'cc-by', 0, NULL);
