INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12063, 'ዘምለጡ እንስሳት', 'tigrigna', 'ኣርባዕተ ኣረግቶት እንስሳት ካብ ኩፍኣት ዋናታቶም ሓራ ንምውፃእ ሓበሩ ፤ ሓደ ዋና ዘይብሉ ገዛ ረኪቦም ድማ ብሰላም ነበሩ። Nível: First words. Ilustração: Magriet Brink.', 'http://africanstorybook.org/illustrations/covers/21111.png', NULL, 2045, 35, 30, 'asp-21111', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12064, 'ማንቲለ በረኻን ምህርቲ ዘፍሪ ዝብኢን', 'tigrigna', 'የዕርኽቲ እዃ እንተኾኑ፣ ማንቲለ ናይ ዝብኢ ዕሽነት ተጠቒማ ኣታሊላቶ። እንተኾነ ግና ኣብ መወዳእታ ነቒሑላ። Nível: First words. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/21112.png', NULL, 2045, 35, 30, 'asp-21112', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12065, 'እታ በቅሊ', 'tigrigna', 'ኣቡኣ ብዘይ ምኽባራ እያ በቅሊ ዘይትወልድ ዝብል ያታዊ ኣባህላ ኣሎ።እዚ ነበረያነበረ እውን በቅሊ ንምንታይ ከምዘይትወልድ ዝገልፅ ልማዳዊ ዛንታ እዩ ። Nível: First words. Ilustração: Marleen Visser.', 'http://africanstorybook.org/illustrations/covers/21113.png', NULL, 2045, 35, 30, 'asp-21113', 'cc-by', 0, NULL);
