INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12067, 'መብራቴና ከተማ', 'am', 'ይህ አስቂኝ ተረት ስለጓደኝነትና ከዘንጋዳ ዘለላ በጥረት ስለሚገኝ ጥቅም ይተርካል፡፡ Nível: First words. Ilustração: Brian Wambi.', 'http://africanstorybook.org/illustrations/covers/21118.png', NULL, 1983, 35, 30, 'asp-21118', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12068, 'ጥሎሽ', 'am', 'እንግዲህ ልጆች! ይህ ተረት ስለአንድ ወጣት ልጅ እና አያቱ ስለሰጡት በጣም አስፈላጊ እንቁላል ነበር፡፡ ነገር ግን ልጁ እንቁላሉን ምን ሊያደርገው እንደሚገባ አርቆ ማሰብ አልቻለም፡፡ እንደእድል ሆኖ ግን በመጨረሻ መልካም እድል ገጠመው፡፡ Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21119.png', NULL, 2046, 35, 30, 'asp-21119', 'cc-by', 0, NULL);
