INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12103, 'ህፃንን ዑፍን', 'tigrigna', 'ሓደ ጉጅለ ኣዕዋፍ ሓንቲ ህፃን ክትበኪ ርኣይኣ፤ምስአን ሒዘንኣ ክበራ ድማ ወሲነን። Nível: First words. Ilustração: Emily Berg.', 'http://africanstorybook.org/illustrations/covers/21170.png', NULL, 2045, 35, 30, 'asp-21170', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12104, 'ለታይን ዝብእን', 'tigrigna', 'ለታይ ተፃዋቲት፣ ህንጥይትን ምዝራብ ብጣዕሚ ትፈቱን ጓል እያ ነይራ። እዚ ባህሪኣ ናብ ፀገም ኣእትይዋ ብኻሊእ ገፅ ድማ ካብ ፀገም ክትወፅእ ሓጊዝዋ። Nível: First words. Ilustração: Jesse Breytenbach.', 'http://africanstorybook.org/illustrations/covers/21171.png', NULL, 2045, 35, 30, 'asp-21171', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12105, 'ነጎዳ ምስ ወዳ', 'tigrigna', 'ነጎዳ ምስ ወዳ ኣብ መሬት እዮም ይነብሩ ነይሮም። ብምኽያት ጥፍኣት ወዳ፣ ካብ ሰብ ርሒቖም ኣብ ሰማይ ክነብሩ ንጉስ ወሲንሎም። Nível: First words. Ilustração: Jesse Breytenbach.', 'http://africanstorybook.org/illustrations/covers/21172.png', NULL, 2045, 35, 30, 'asp-21172', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12106, 'ዋዕሮን ሰገንን', 'tigrigna', 'ሰገን ንዋዕሮ ብጣዕሚ ኣመነታ። ዋዕሮ ግን እቶም ብጣዕሚ ዝረጎዱ ደቂ ሰገን ንባዕላ ንምውሳድን ደቃ ንምግባርን መደብ ኣውፅኣት። Nível: First words. Ilustração: Brian Wambi.', 'http://africanstorybook.org/illustrations/covers/21173.png', NULL, 2045, 35, 30, 'asp-21173', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12107, 'የፀጉር ምርጫዎቻችን', 'am', 'ህፃናት እንደየፍላጎታቸው ሁኔታ የተለያዩ የፀጉር አሰራር ምርጫዎችን ይመርጣሉ፡፡ Nível: First sentences. Ilustração: Bronwen Heath, Catherine Groenewald and Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21177.png', NULL, 2048, 35, 30, 'asp-21177', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12108, 'ሓርገፅን ከልብን', 'tigrigna', 'ከልቢ ኣብ ደንደስ ሩባ እንቛቕሖ ረኺቡ ናብ ገዝኡ ወሰዶ። እታ ብዓልቲ እንቛቕሖ ሓርገፅ ምውሳዶም ምስ ፈለጠት እንታይ ከምትገብር ንትዓዘብ። Nível: First words. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/21178.png', NULL, 2045, 35, 30, 'asp-21178', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12109, 'ዋርዲት በቅሎዋ', 'am', 'በቅሎ ለምን ልጅ እንደማትወልድ የሚያስረዳ ተረት፡፡ (ይህን ተረት መጀመሪያ የተረኩልን መስፍን ሀብተማርያም ናቸው፡፡ ኤሊዛቤት ሊያርድ ደግሞ ወደ እንግሊዝኛ ተረጎሙት፡፡ ) Nível: First words. Ilustração: Marleen Visser.', 'http://africanstorybook.org/illustrations/covers/21180.png', NULL, 1983, 35, 30, 'asp-21180', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12110, 'ያመለጡት እንስሳት', 'am', 'አራት በዕድሜ የገፉ እንስሳት ራሳቸውን ከጨቋኝ ጌቶቻቸው ነጻ ለማውጣት ተባበሩ፡፡ የእርጅና ዘመናቸውንም በሰላም ለማሳለፍ የሚችሉበትን ቦታ አገኙ፡፡ Nível: First words. Ilustração: Magriet Brink.', 'http://africanstorybook.org/illustrations/covers/21181.png', NULL, 1983, 35, 30, 'asp-21181', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12111, 'ጭራቆች ደደቦች ናቸው', 'am', 'ሙሉና ቤተሰቡ ድርቅ ስለመጣባቸው ምግብ እየፈለጉ ነው፡፡ አንድ ማሳ አግኝተው ባለቤቱ ከምርቱ  እንዲመገቡ ፈቀደላቸው፡፡ ለበሉት ምግብ ግን እጅግ ከፍተኛ ክፍያ መክፈል ይኖርባቸዋል፡፡ Nível: First words. Ilustração: Natalie Propa.', 'http://africanstorybook.org/illustrations/covers/21182.png', NULL, 1983, 35, 30, 'asp-21182', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12112, 'መታለሊ ማንቲለ', 'tigrigna', 'ማንቲለ ምትላሉ ቐፂሉ ኣሎ። ሕዚ ክኣ እንታይ ከምዝገብር እዚ ታሪኽ ኣንብቡ እሞ እስቲ ተዓዘቡ። Nível: First words. Ilustração: Abraham Muzee.', 'http://africanstorybook.org/illustrations/covers/21183.png', NULL, 2045, 35, 30, 'asp-21183', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12113, 'ጉየይ ማንቲለ፣ ጉየይ', 'tigrigna', 'ማንቲለ ደቂሳ እንተላ ወዝቢ ቱፋሕ ካብ ኦም ወደቐ ምስኡ ድማ ጉየይ ማንቲለ ጉየይ ዝብል ዘረባ ሰምዐት። እዚ ናይ እዚ ታሪኽ መጀመርታ እዩ። Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21188.png', NULL, 2045, 35, 30, 'asp-21188', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12114, 'Nguli Na King''ang''í', 'kikamba', 'Undu Nguli yeeyovoisye kuuma kanywani ka Kingángi. Nível: First words. Ilustração: Abraham Muzee.', 'http://africanstorybook.org/illustrations/covers/21193.png', NULL, 2030, 35, 30, 'asp-21193', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12115, 'ዘይምምእዛዝ', 'tigrigna', 'ሓንቲ ደረቐኛ ሓሰማ ንሓንቲ ሓረስተይቲ ኣይምእዘዝን ኢላ ኣበየታ። ኣብ መወዳእታ ግን መዘዙ ፈሪሓ ዝትኣዘዘቶ ፈፀመት። Nível: First words. Ilustração: Marion Drew.', 'http://africanstorybook.org/illustrations/covers/21194.png', NULL, 2045, 35, 30, 'asp-21194', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12116, 'እታ ዝሞተት ዕትሮ', 'tigrigna', 'ዓንደ ንእሽተይ ዑትሮ ነይርዎ ኮይኑ ግን ዓብይ ዑትሮ ክህልዎ ተመንዩ። እዚ ዓብይ ዑትሮ ንምርካብ ብዙሕ ሓሲቡ። ብዝሓሰቦ መሰረት ተሳኺዑሉ ዓብይ ዕትሮ ረኺቡ። Nível: First words. Ilustração: Emily Berg.', 'http://africanstorybook.org/illustrations/covers/21195.png', NULL, 2045, 35, 30, 'asp-21195', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12117, 'ቅርስስቲ መዓልቲ', 'tigrigna', 'እዚ ታሪኽ ብዛዕባ ክልተ ተጨወዩ ቆልዑ እዩ። እቶም ቆልዑ ሓደጋ ኣብ ዘለዎ ጉዕዞ ኣትዮም ነይሮም፤ ኣብ መወዳእታ ግን ድሒኖም። Nível: First words. Ilustração: Abraham Muzee.', 'http://africanstorybook.org/illustrations/covers/21197.png', NULL, 2045, 35, 30, 'asp-21197', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12118, 'Buugi', 'lusoga', 'Maama azirawo era Bbaabba afumba buugi wa kyankyo. Nível: First words. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/21198.png', NULL, 1245, 35, 30, 'asp-21198', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12119, 'Kkapa Yange Eri Wa?', 'lg', 'Kkapa yange embuzeeko. Olina w’olabye kkapa yange? Nível: First words. Ilustração: Bronwen Heath.', 'http://africanstorybook.org/illustrations/covers/2120.png', NULL, 1333, 35, 30, 'asp-2120', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12120, 'Ingona Yari Ishonje', 'rw', 'Ingona yari ishonje yagiye yerekeza ku mazi. Nível: First sentences. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21204.png', NULL, 1970, 35, 30, 'asp-21204', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12121, 'Umurobyi Jaaka', 'rw', 'A description of the life of a hardworking Nile fisherman. Ibiranga umurobyi wa Nil wakoraga cyane. Nível: First words. Ilustração: Zablon Alex Nguku.', 'http://africanstorybook.org/illustrations/covers/21205.png', NULL, 1970, 35, 30, 'asp-21205', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12122, 'Igishyimbo Kimeze', 'rw', 'Tera igishyimbo ubundi urebe nyuma iyo wakivomereye kandi wakitayeho neza. Nível: First words. Ilustração: Mlungisi Dlamini.', 'http://africanstorybook.org/illustrations/covers/21207.png', NULL, 1970, 35, 30, 'asp-21207', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12123, 'Puusi Na Wambwa Bakuba Na Kusiiga', 'lusoga', 'Puusi ni Wambwa ba mukwano. Basesa era beeyagala nga bakolera kino ni kire ghalala. Nível: Longer paragraphs. Ilustração: Elke and René Leisink.', 'http://africanstorybook.org/illustrations/covers/21209.png', NULL, 1245, 35, 30, 'asp-21209', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12124, 'Nakungu N’Embulu', 'lunyole', 'Hale ŋaliŋo omusinde omwafu n’omuhasi wuwe. Abaatu bano baali n’omwana mulala muhana ni bamulanga baati Nakungu. Nível: Read aloud. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/2121.png', NULL, 1681, 35, 30, 'asp-2121', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12125, 'ጥንቸልና ጅብ', 'am', 'በድሮ ዘመን አንዲት ጥንቸልና አንድ ጅብ በአንድ ላይ ይኖሩ ነበር፡፡ ጥንቸል በጣም ጎበዝ ነበረች፡፡ ሁሌም ከሰነፉ ጅብ በተሻለ ብዙ ምግብ የምታከማቸው ጥንቸል ነበረች፡፡ ጅቡ ስራ ላይ በጣም ሰነፉ ቢሆንም ምግብ መብላት ግን በጣም ይወድ ነበር፡፡ ምን ይፈጠር ይሆን? Nível: First paragraphs. Ilustração: Wiehan de Jager and Rob Owen.', 'http://africanstorybook.org/illustrations/covers/21218.png', NULL, 2049, 35, 30, 'asp-21218', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12126, 'Clouds', 'en', 'What clouds bring to the environment. Nível: First sentences. Ilustração: Microsoft Clip Art.', 'http://africanstorybook.org/illustrations/covers/2122.png', NULL, 2050, 35, 30, 'asp-2122', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12127, 'Dɔwa’Alli Pam', 'mampruli', 'Dɔwa’ali sufu ŋɔn bɛ buni an wa’a ni an gyi. Nível: First words. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/21220.png', NULL, 2051, 35, 30, 'asp-21220', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12128, 'Bɔ Ka I Niŋna?', 'mampruli', 'Deema balgu. Bɔ ka i niŋna? N yuumni ni Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/21221.png', NULL, 2051, 35, 30, 'asp-21221', 'cc-by', 0, NULL);
