INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12138, 'ውለታቢሱ ቀበሮ', 'am', 'ጥንቸል በአስቸጋሪ ወቅት ቀበሮውን አዳነችው፡፡ ነገር ግን ቀበሮው ቃል በገባው መሰረት ለጥንቸል ውለታዋን መክፈል ሲገባው ቃሉን አጠፈ፣ መሃላውን አፈረሰ፡፡ Nível: First words. Ilustração: Jacob Kono.', 'http://africanstorybook.org/illustrations/covers/21243.png', NULL, 2046, 35, 30, 'asp-21243', 'cc-by', 0, NULL);
